import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<
    typeof Ajv
  >[0]);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition, name: string): ValidateFunction {
    if (tool.staticValidator) return tool.staticValidator;
    const schema = definition.inputSchema;
    const cached = this.validators.get(schema);
    if (cached) return cached;
    let validator: ValidateFunction;
    try {
      validator = this.ajv.compile(schema);
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}`, {cause: error});
    }
    this.validators.set(schema, validator);
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        staticValidator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for the rejection and unknown-tool contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(tool, definition, name);
    if (!validator(input)) {
      const failures = (validator.errors ?? []).map(error => {
        const params = error.params as Record<string, unknown>;
        const legacyPath = (error as {dataPath?: string}).dataPath;
        const instancePath =
          (error as {instancePath?: string}).instancePath ??
          legacyPath?.replace(/\[(\d+)\]/g, '/$1').replace(/\./g, '/') ??
          '';
        const namedProperty =
          error.keyword === 'required'
            ? params.missingProperty
            : error.keyword === 'additionalProperties'
              ? params.additionalProperty
              : undefined;
        let path = instancePath || '/';
        if (namedProperty !== undefined) {
          const property = String(namedProperty).replace(/~/g, '~0').replace(/\//g, '~1');
          path = `${instancePath}/${property}`;
        }
        let constraint = error.keyword;
        if (error.keyword === 'type') constraint = `expected ${String(params.type)}`;
        if (error.keyword === 'enum' && Array.isArray(params.allowedValues)) {
          const allowedValues = params.allowedValues.map(String);
          constraint = `expected one of ${allowedValues.join(', ')}`;
        }
        return `${path}: ${constraint}`;
      });
      const result = failures.join('; ') || 'schema validation failed';
      log.warn('tool', 'input rejected', {name, failures});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#7
  it('names the tool when registration rejects an invalid static schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather lookup',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  // specs/hal-engine-tool-input-validation/spec.md#10
  it('validates each dynamic schema and reuses a schema object validator', async () => {
    const registry = new ToolRegistry();
    const locationSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const zipSchema = {type: 'object', properties: {zip: {type: 'string'}}, required: ['zip']};
    let currentSchema: Record<string, unknown> = locationSchema;
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({name: 'weather', description: 'Weather lookup', inputSchema: currentSchema}),
      async input => {
        inputs.push(input);
        return 'forecast';
      }
    );

    const missingLocation = await registry.execute('weather', {});
    currentSchema = zipSchema;
    const validZip = await registry.execute('weather', {zip: '12345'});
    const missingZip = await registry.execute('weather', {location: 'Paris'});
    currentSchema = locationSchema;
    const validLocation = await registry.execute('weather', {location: 'Paris'});

    expect({
      missingLocationIsRequired: /location.*required|required.*location/.test(missingLocation.result),
      validZip: validZip.result,
      missingZipIsRequired: /zip.*required|required.*zip/.test(missingZip.result),
      validLocation: validLocation.result,
      inputs,
    }).toEqual({
      missingLocationIsRequired: true,
      validZip: 'forecast',
      missingZipIsRequired: true,
      validLocation: 'forecast',
      inputs: [{zip: '12345'}, {location: 'Paris'}],
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#4
  it('names a wrong-typed property path without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup',
        description: 'Look up an identifier',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}},
      },
      async () => {
        executorCalls += 1;
        return 'unreachable';
      }
    );

    const response = await registry.execute('lookup', {identifier: 123456789});

    expect({
      result: response.result,
      executorCalls,
    }).toEqual({
      result: '/identifier: expected string',
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#12
  it('names an explicitly forbidden extra property without exposing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up an identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          additionalProperties: false,
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('lookup', {identifier: 'safe', secret: '123456789'});

    expect(response).toEqual({result: '/secret: additionalProperties'});
  });

  // specs/hal-engine-tool-input-validation/spec.md#13
  it('names allowed enum choices without exposing the rejected value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'unreachable';
      }
    );

    const response = await registry.execute('weather', {unit: 'private-value'});

    expect({result: response.result, executorCalls}).toEqual({
      result: '/unit: expected one of celsius, fahrenheit',
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#14
  it('escapes a slash in a required property path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up an identifier',
        inputSchema: {type: 'object', required: ['account/id']},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('lookup', {});

    expect(response).toEqual({result: '/account~1id: required'});
  });
});

